import json
import pkgutil

from .dlc import select_data

# Generated by tools/build_ap_data.py from the game's definition dump; the mod embeds the same file.
DATA = json.loads(pkgutil.get_data(__name__, "data/reus2.json").decode("utf-8"))


def selected_data(ice_age: bool = False, everglades: bool = False,
                  grasslands: bool = False, jurassic: bool = False):
    """Return the game data enabled by a seed's DLC options."""
    return select_data(DATA, ice_age, everglades, grasslands, jurassic)
